    var name = metadata.deviceName;
    if (name.length() == 9 && name.substring(4, 6) ==
        "LW") {
        var yr = parseInt(name.substring(0, 2));
        if (yr != null) {
            // old decoders:
            if (yr != null && yr <= 21) {
                decoderVersion = "2021";
            } else if (yr != null && yr == 22) {
                decoderVersion = "2022";
            } else if (msg.attributes != null) {
                var attrs = msg.attributes;
                if (attrs.deviceEUI != null) {
                    dev = attrs.deviceEUI;
                    if (dev.length() >= 4) {
                        // RAK radio chip
                        if (dev.substring(0, 4) == "AC1F") {
                            decoderVersion = "Gen2";
                            // RN "Microchip" radio chip
                        } else if (dev.substring(0, 4) ==
                            "0004") {
                            var ym = parseInt(name
                                .substring(0, 4)); // yymm
                            var n = parseInt(name.substring(
                                6, 9)); // NNN
                            // between 2023 and 2025 August batch No. 021 or lower.
                            if ((ym > 2300 && ym < 2508) ||
