// Bit-reading utilities by Rytis 2026-04-02

function round0(x) {
    if (x == null) {
        return null;
    }
    return Math.round(x);
}

function round1(x) {
    if (x == null) {
        return null;
    }
    return Math.round(x * 10.0) / 10.0;
}

function round2(x) {
    if (x == null) {
        return null;
    }
    return Math.round(x * 100.0) / 100.0;
}

function error_msg(text) {
    return {
        msg: {
            error: text,
            raw: msg.frmPayload,
            fCnt: msg.fCnt
        },
        metadata: metadata != null ? metadata : {},
        msgType: msgType != null ? msgType : "POST_TELEMETRY_REQUEST"
    };
}

function bytesToBits(bytes) {
    var bits = [];

    for (var i = 0; i < bytes.length; i++) {
        var b = bytes[i];

        // normalize signed → unsigned
        if (b < 0) {
            b += 256;
        }

        // extract bits (MSB → LSB)
        for (var j = 7; j >= 0; j--) {
            bits.push((b >> j) & 1);
        }
    }

    return bits;
}
// Base64 to bits.
function newBitReader(b64) {
    if (b64 == null) {
        return null;
    }

    var raw = base64ToBytesList(b64);
    var bytes = [];
    for (var i = 0; i < raw.length; i++) {
        var b = raw[i];
        if (b < 0) {
            b = b + 256;
        }
        bytes.push(b);
    }

    if (bytes.length == 0) {
        return null;
    }
    var bits = bytesToBits(bytes);

    return {
        repr: bits,
        pos: 0
    };
}

function readBits(br, N) {
    if (br == null) {
        return null;
    }

    if (br.repr == null) {
        return null;
    }

    if (br.pos == null) {
        return null;
    }

    if (N == null || N <= 0) {
        return 0;
    }

    var len = br.repr.length;

    if (br.pos + N > len) {
        return null;
    }

    var value = 0;
    var i = 0;

    while (i < N) {
        var idx = br.pos;

        // safe index check (TBEL defensive)
        if (idx < 0 || idx >= len) {
            return null;
        }

        var bit = br.repr[idx];

        // ensure valid bit
        if (bit == null) {
            return null;
        }

        if (bit != 0 && bit != 1) {
            return null;
        }

        // accumulate (MSB-first)
        value = (value * 2) + bit;

        // advance position
        br.pos = br.pos + 1;
        i = i + 1;
    }

    return value;
}

function readBitsValid(br, N)  {
    var tmp = readBits(br, N);
    return (tmp!=null && tmp<parseInt(1<<N) ? tmp: null);
